import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_05_mc_pipeline.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_05_return_backward.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_05_first_every_visit.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_05_mc_control_loop.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_05_dp_mc_td.png",f=JSON.parse('{"title":"不知道环境模型，也能学会决策？蒙特卡洛方法讲透了","description":"动态规划像拿着一张完整地图做计算：每个动作会去哪里、概率是多少、能得到什么奖励，全都提前知道。现实中的智能体通常没有这张地图。蒙特卡洛方法（Monte Carlo Methods，蒙特卡洛方法）给出的答案非常直接：先按策略真正走完许多回合，再用亲身经历过的完整回报估计价值。","frontmatter":{"title":"不知道环境模型，也能学会决策？蒙特卡洛方法讲透了","description":"动态规划像拿着一张完整地图做计算：每个动作会去哪里、概率是多少、能得到什么奖励，全都提前知道。现实中的智能体通常没有这张地图。蒙特卡洛方法（Monte Carlo Methods，蒙特卡洛方法）给出的答案非常直接：先按策略真正走完许多回合，再用亲身经历过的完整回报估计价值。","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":20,"source":"2026-08-13/rl_series_05_monte_carlo.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_05_mc_pipeline.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-05-monte-carlo"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"不知道环境模型，也能学会决策？蒙特卡洛方法讲透了"}],["meta",{"property":"og:description","content":"动态规划像拿着一张完整地图做计算：每个动作会去哪里、概率是多少、能得到什么奖励，全都提前知道。现实中的智能体通常没有这张地图。蒙特卡洛方法（Monte Carlo Methods，蒙特卡洛方法）给出的答案非常直接：先按策略真正走完许多回合，再用亲身经历过的完整回报估计价值。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-05-monte-carlo"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_05_mc_pipeline.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"不知道环境模型，也能学会决策？蒙特卡洛方法讲透了"}],["meta",{"name":"twitter:description","content":"动态规划像拿着一张完整地图做计算：每个动作会去哪里、概率是多少、能得到什么奖励，全都提前知道。现实中的智能体通常没有这张地图。蒙特卡洛方法（Monte Carlo Methods，蒙特卡洛方法）给出的答案非常直接：先按策略真正走完许多回合，再用亲身经历过的完整回报估计价值。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_05_mc_pipeline.png"}]],"prev":{"text":"价值是怎样从终点倒着传回来的？一篇看懂动态规划","link":"/rl/rl-series-04-dynamic-programming"},"next":{"text":"不用等到终点就能学习：时序差分为什么是强化学习的转折点","link":"/rl/rl-series-06-temporal-difference"}},"headers":[],"relativePath":"rl/rl-series-05-monte-carlo.md","filePath":"rl/rl-series-05-monte-carlo.md","lastUpdated":null}'),p={name:"rl/rl-series-05-monte-carlo.md"};function d(c,a,_,b,u,m){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="不知道环境模型-也能学会决策-蒙特卡洛方法讲透了" tabindex="-1">不知道环境模型，也能学会决策？蒙特卡洛方法讲透了 <a class="header-anchor" href="#不知道环境模型-也能学会决策-蒙特卡洛方法讲透了" aria-label="Permalink to &quot;不知道环境模型，也能学会决策？蒙特卡洛方法讲透了&quot;">​</a></h1><p>动态规划像拿着一张完整地图做计算：每个动作会去哪里、概率是多少、能得到什么奖励，全都提前知道。现实中的智能体通常没有这张地图。蒙特卡洛方法（Monte Carlo Methods，蒙特卡洛方法）给出的答案非常直接：先按策略真正走完许多回合，再用亲身经历过的完整回报估计价值。</p><p>这一步看似只是把“精确期望”换成“样本平均”，却是强化学习从规划走向学习的关键转折。智能体不再要求环境交出状态转移概率，而是从一条条轨迹中回答两个问题：当前策略到底有多好，以及怎样让后续策略更好。</p><p>本文讨论的是经典回合式蒙特卡洛方法。它的核心优点是免模型、不自举、概念透明；核心代价是必须等待回合结束、样本效率有限、回报方差可能很高。理解这些取舍，才能看懂后面的时序差分学习（Temporal-Difference Learning，时序差分学习）、Sarsa 和 Q-learning（Q 学习）究竟改进了什么。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-蒙特卡洛学习的是样本回报的平均" tabindex="-1">1.1 蒙特卡洛学习的是样本回报的平均 <a class="header-anchor" href="#_1-1-蒙特卡洛学习的是样本回报的平均" aria-label="Permalink to &quot;1.1 蒙特卡洛学习的是样本回报的平均&quot;">​</a></h3><p>给定策略 (\\pi)，状态 (s) 的真实价值是从该状态出发后折扣回报的期望。环境模型未知时，我们不能枚举所有未来分支，但可以反复采样轨迹。只要样本来自目标策略并满足相应统计条件，回报的经验平均就会逐渐逼近价值函数。</p><h3 id="_1-2-它免模型-但不等于没有前提" tabindex="-1">1.2 它免模型，但不等于没有前提 <a class="header-anchor" href="#_1-2-它免模型-但不等于没有前提" aria-label="Permalink to &quot;1.2 它免模型，但不等于没有前提&quot;">​</a></h3><p>经典蒙特卡洛方法需要能获得完整回报，因此通常面向最终会终止的回合式任务。它还要求被估计的状态或状态动作对得到足够访问。做控制时，如果某些动作永远不被尝试，它们的价值就没有可靠证据，策略改进也可能过早停在局部选择上。</p><h3 id="_1-3-它用真实回报-不使用自举目标" tabindex="-1">1.3 它用真实回报，不使用自举目标 <a class="header-anchor" href="#_1-3-它用真实回报-不使用自举目标" aria-label="Permalink to &quot;1.3 它用真实回报，不使用自举目标&quot;">​</a></h3><p>动态规划用模型计算期望，并使用已经估计的后继价值；时序差分方法也会把后继价值放进学习目标。蒙特卡洛方法一直等到终点，用实际观测到的后续奖励构造 (G_t)。目标没有包含当前价值估计，因此不自举，但一次随机轨迹可能带来很大波动。</p><h3 id="_1-4-从预测到控制仍然依靠-评估加改进" tabindex="-1">1.4 从预测到控制仍然依靠“评估加改进” <a class="header-anchor" href="#_1-4-从预测到控制仍然依靠-评估加改进" aria-label="Permalink to &quot;1.4 从预测到控制仍然依靠“评估加改进”&quot;">​</a></h3><p>蒙特卡洛预测估计固定策略的价值；蒙特卡洛控制则在估计动作价值 (Q(s,a)) 后，让高价值动作获得更高选择概率。它延续了广义策略迭代（Generalized Policy Iteration，广义策略迭代）的骨架，只是把动态规划中的完整模型备份换成了采样回报。</p><p><img src="'+o+'" alt="蒙特卡洛方法从轨迹到价值再到策略的完整流程"></p><h2 id="二、为什么动态规划到了现实中会卡住" tabindex="-1">二、为什么动态规划到了现实中会卡住 <a class="header-anchor" href="#二、为什么动态规划到了现实中会卡住" aria-label="Permalink to &quot;二、为什么动态规划到了现实中会卡住&quot;">​</a></h2><h3 id="_2-1-动态规划需要的不只是一个模拟器" tabindex="-1">2.1 动态规划需要的不只是一个模拟器 <a class="header-anchor" href="#_2-1-动态规划需要的不只是一个模拟器" aria-label="Permalink to &quot;2.1 动态规划需要的不只是一个模拟器&quot;">​</a></h3><p>动态规划更新某个状态时，需要知道每个动作下全部可能的后继状态、对应概率和奖励。一个环境即使能运行仿真，也未必能显式给出这张概率表。能够调用一次仿真得到样本，与能够列出完整转移分布，是两种完全不同的能力。</p><p>自动驾驶环境尤其如此。前车会不会急刹、行人会不会横穿、感知误差怎样变化，往往只能通过数据或仿真获得有限样本，很难写成可枚举且准确的转移概率。状态维度一旦包含周围交通参与者、道路结构和历史信息，完整遍历也会迅速失去可计算性。</p><h3 id="_2-2-样本把-求和-变成了-经历" tabindex="-1">2.2 样本把“求和”变成了“经历” <a class="header-anchor" href="#_2-2-样本把-求和-变成了-经历" aria-label="Permalink to &quot;2.2 样本把“求和”变成了“经历”&quot;">​</a></h3><p>假设从状态 (s) 出发，未来可能出现大量分支。动态规划试图对所有分支加权求和；蒙特卡洛方法只沿策略采样其中一条路径，记下这条路径的回报。一次经历不能代表期望，多次独立或适当采样的经历取平均后，却可以提供统计估计。</p><p>这就是免模型（Model-Free，免模型）的准确含义：学习算法不要求显式使用环境转移概率和奖励函数。它不代表环境没有规律，也不代表智能体什么结构都不需要。状态、动作、奖励、回合终止条件和数据采集策略仍然必须定义清楚。</p><h2 id="三、轨迹、回合与回报到底是什么" tabindex="-1">三、轨迹、回合与回报到底是什么 <a class="header-anchor" href="#三、轨迹、回合与回报到底是什么" aria-label="Permalink to &quot;三、轨迹、回合与回报到底是什么&quot;">​</a></h2><h3 id="_3-1-一条轨迹记录完整交互过程" tabindex="-1">3.1 一条轨迹记录完整交互过程 <a class="header-anchor" href="#_3-1-一条轨迹记录完整交互过程" aria-label="Permalink to &quot;3.1 一条轨迹记录完整交互过程&quot;">​</a></h3><p>一个回合可以写成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S₀, A₀, R₁, S₁, A₁, R₂, …, Sₜ</span></span></code></pre></div><p>这里 (S_t) 是时刻 (t) 的状态，(A_t) 是智能体采取的动作，(R_{t+1}) 是动作之后得到的奖励，(S_T) 是终止状态。策略 (\\pi(a|s)) 决定在状态 (s) 下如何选择动作，环境则产生下一状态和奖励。</p><h3 id="_3-2-回报从当前时刻累积到终点" tabindex="-1">3.2 回报从当前时刻累积到终点 <a class="header-anchor" href="#_3-2-回报从当前时刻累积到终点" aria-label="Permalink to &quot;3.2 回报从当前时刻累积到终点&quot;">​</a></h3><p>时刻 (t) 的折扣回报定义为：</p><p>$$ G_t=R_{t+1}+\\gamma R_{t+2}+\\gamma^2R_{t+3}+\\cdots+\\gamma^{T-t-1}R_T $$</p><p>折扣因子 (\\gamma\\in[0,1]) 控制远期奖励的权重。一次回合结束后，可以从最后一个奖励向前递推：</p><p>$$ G_t=R_{t+1}+\\gamma G_{t+1} $$</p><p>这不是贝尔曼自举。右侧的 (G_{t+1}) 已经由同一条完整轨迹中的真实奖励算出，并不是拿当前估计的 (V(S_{t+1})) 代替未知未来。</p><p><img src="'+l+'" alt="完整回合结束后从终点向前计算每个时刻的回报"></p><h3 id="_3-3-回合必须有清晰终止语义" tabindex="-1">3.3 回合必须有清晰终止语义 <a class="header-anchor" href="#_3-3-回合必须有清晰终止语义" aria-label="Permalink to &quot;3.3 回合必须有清晰终止语义&quot;">​</a></h3><p>棋局结束、车辆到达目标、碰撞、超时都可以定义为终止事件，但它们的语义不同。到达或碰撞属于任务本身结束；训练系统人为设置的最大时长更接近截断（Truncation，截断）。如果截断时把未来价值一律当成零，价值估计可能产生系统偏差。</p><p>因此，“运行固定时长后停下来”不能自动等同于获得完整回报。经典蒙特卡洛教学通常假设回合自然终止；持续式任务需要另行设计回合边界、尾部价值处理或采用更适合在线更新的方法。</p><h2 id="四、蒙特卡洛预测怎样估计状态价值" tabindex="-1">四、蒙特卡洛预测怎样估计状态价值 <a class="header-anchor" href="#四、蒙特卡洛预测怎样估计状态价值" aria-label="Permalink to &quot;四、蒙特卡洛预测怎样估计状态价值&quot;">​</a></h2><h3 id="_4-1-预测问题先固定策略" tabindex="-1">4.1 预测问题先固定策略 <a class="header-anchor" href="#_4-1-预测问题先固定策略" aria-label="Permalink to &quot;4.1 预测问题先固定策略&quot;">​</a></h3><p>预测不是寻找最佳动作，而是评估给定策略 (\\pi)。状态价值定义为：</p><p>$$ v_\\pi(s)=\\mathbb{E}_\\pi[G_t\\mid S_t=s] $$</p><p>期望下标说明，轨迹中的动作由策略 (\\pi) 产生，后续状态和奖励由环境产生。蒙特卡洛方法收集状态 (s) 被访问后的多个回报，把这些回报求平均，得到 (V(s)) 对 (v_\\pi(s)) 的估计。</p><h3 id="_4-2-更新发生在回合结束之后" tabindex="-1">4.2 更新发生在回合结束之后 <a class="header-anchor" href="#_4-2-更新发生在回合结束之后" aria-label="Permalink to &quot;4.2 更新发生在回合结束之后&quot;">​</a></h3><p>采样时先保存状态、动作和奖励序列。到达终点后，从后向前计算每个时刻的 (G_t)，再把对应回报加入状态统计。与动态规划遍历所有状态不同，蒙特卡洛方法只更新本次轨迹实际访问的部分。</p><p>这种局部更新在巨大状态空间中很有吸引力：没有被访问的状态不消耗更新计算。但它也暴露了数据覆盖问题。罕见状态如果几乎从不出现，价值表就很难获得稳定估计；完全没有出现的状态更不可能凭空学会。</p><h2 id="五、首次访问与每次访问差在哪里" tabindex="-1">五、首次访问与每次访问差在哪里 <a class="header-anchor" href="#五、首次访问与每次访问差在哪里" aria-label="Permalink to &quot;五、首次访问与每次访问差在哪里&quot;">​</a></h2><h3 id="_5-1-首次访问只使用回合内的首次命中" tabindex="-1">5.1 首次访问只使用回合内的首次命中 <a class="header-anchor" href="#_5-1-首次访问只使用回合内的首次命中" aria-label="Permalink to &quot;5.1 首次访问只使用回合内的首次命中&quot;">​</a></h3><p>首次访问蒙特卡洛（First-Visit Monte Carlo，首次访问蒙特卡洛）规定：对于某个状态，只把该状态在本回合首次出现之后的回报加入平均。如果轨迹绕路后再次回到同一状态，后续访问不再为这个状态新增样本。</p><p>注意“首次”是相对于单个回合，不是整个训练过程。新回合开始后，同一状态再次出现，仍然会贡献一个新的首次访问样本。</p><h3 id="_5-2-每次访问使用回合内的全部命中" tabindex="-1">5.2 每次访问使用回合内的全部命中 <a class="header-anchor" href="#_5-2-每次访问使用回合内的全部命中" aria-label="Permalink to &quot;5.2 每次访问使用回合内的全部命中&quot;">​</a></h3><p>每次访问蒙特卡洛（Every-Visit Monte Carlo，每次访问蒙特卡洛）会使用该状态在回合中的每一次出现。若状态 (s) 在同一轨迹出现三次，就会加入三个不同时间点的回报。</p><p>在满足常见条件时，两种方法都能收敛到相应价值。区别在于样本组织方式：首次访问更容易对应“每个回合一个样本”的分析；每次访问复用更多访问，但同一回合内的多个回报彼此相关，不能简单当作完全独立样本。</p><p><img src="'+h+'" alt="同一回合中首次访问与每次访问的样本选择差异"></p><h3 id="_5-3-实现时最容易把方向写反" tabindex="-1">5.3 实现时最容易把方向写反 <a class="header-anchor" href="#_5-3-实现时最容易把方向写反" aria-label="Permalink to &quot;5.3 实现时最容易把方向写反&quot;">​</a></h3><p>如果从轨迹尾部倒序遍历，看到的状态顺序与正向的“首次访问”并不相同。稳妥做法是先明确要判断的索引：只有当当前索引是该状态在正向轨迹中的首次出现时才更新，或者正向预先记录首次位置，再反向计算回报。</p><p>另一个常见问题是把状态访问与状态动作访问混在一起。估计 (V(s)) 时按状态判断；估计 (Q(s,a)) 时必须按二元组 ((s,a)) 判断。同一状态选择了不同动作，应当属于不同的动作价值样本。</p><h2 id="六、为什么可以用平均回报逼近价值" tabindex="-1">六、为什么可以用平均回报逼近价值 <a class="header-anchor" href="#六、为什么可以用平均回报逼近价值" aria-label="Permalink to &quot;六、为什么可以用平均回报逼近价值&quot;">​</a></h2><h3 id="_6-1-价值本来就是条件期望" tabindex="-1">6.1 价值本来就是条件期望 <a class="header-anchor" href="#_6-1-价值本来就是条件期望" aria-label="Permalink to &quot;6.1 价值本来就是条件期望&quot;">​</a></h3><p>在策略保持固定、回合分布稳定且状态得到持续访问时，每次访问后观察到的 (G_t) 可以看作目标分布的样本。样本数量增加后，经验平均会依据大数定律趋近条件期望。这不是强化学习特有的魔法，而是统计估计在序列决策问题中的应用。</p><h3 id="_6-2-有限样本仍然可能很不可靠" tabindex="-1">6.2 有限样本仍然可能很不可靠 <a class="header-anchor" href="#_6-2-有限样本仍然可能很不可靠" aria-label="Permalink to &quot;6.2 有限样本仍然可能很不可靠&quot;">​</a></h3><p>如果一个状态只访问两次，平均值并不会因为写进价值表就变得可信。应同时记录访问次数、回报方差或置信区间，并用多随机种子重复实验。只报告最终一张价值表，会隐藏样本不足与偶然轨迹的影响。</p><p>状态访问分布还可能随策略更新而变化。做控制时，早期回报来自旧策略，后期回报来自新策略，数据不再严格同分布。表格型蒙特卡洛控制依靠持续探索和逐步改进工作，但工程分析仍应警惕把所有历史样本视为完全静态的数据集。</p><h2 id="七、增量平均为什么值得单独理解" tabindex="-1">七、增量平均为什么值得单独理解 <a class="header-anchor" href="#七、增量平均为什么值得单独理解" aria-label="Permalink to &quot;七、增量平均为什么值得单独理解&quot;">​</a></h2><h3 id="_7-1-保存全部回报没有必要" tabindex="-1">7.1 保存全部回报没有必要 <a class="header-anchor" href="#_7-1-保存全部回报没有必要" aria-label="Permalink to &quot;7.1 保存全部回报没有必要&quot;">​</a></h3><p>假设状态 (s) 已有 (N(s)-1) 个回报样本，新样本是 (G_t)。精确样本均值可以增量更新：</p><p>$$ N(s)\\leftarrow N(s)+1 $$</p><p>$$ V(s)\\leftarrow V(s)+\\frac{1}{N(s)}\\left[G_t-V(s)\\right] $$</p><p>方括号中的 (G_t-V(s)) 是蒙特卡洛误差。新回报高于当前估计时，价值上升；低于当前估计时，价值下降。更新幅度随访问次数增多而减小，不必保存历史回报列表。</p><h3 id="_7-2-固定学习率改变了统计含义" tabindex="-1">7.2 固定学习率改变了统计含义 <a class="header-anchor" href="#_7-2-固定学习率改变了统计含义" aria-label="Permalink to &quot;7.2 固定学习率改变了统计含义&quot;">​</a></h3><p>也可以把 (1/N(s)) 换成固定学习率 (\\alpha)：</p><p>$$ V(s)\\leftarrow V(s)+\\alpha\\left[G_t-V(s)\\right] $$</p><p>这时得到的不再是所有历史样本的普通算术平均，而是对近期样本赋予更大权重的指数加权估计。固定 (\\alpha) 可能更适合非平稳环境，但会持续保留随机波动。二者没有无条件的优劣，关键是实验目标究竟是估计固定分布，还是跟踪变化中的分布。</p><h2 id="八、为什么控制问题更关心动作价值" tabindex="-1">八、为什么控制问题更关心动作价值 <a class="header-anchor" href="#八、为什么控制问题更关心动作价值" aria-label="Permalink to &quot;八、为什么控制问题更关心动作价值&quot;">​</a></h2><h3 id="_8-1-只有状态价值还不够直接选动作" tabindex="-1">8.1 只有状态价值还不够直接选动作 <a class="header-anchor" href="#_8-1-只有状态价值还不够直接选动作" aria-label="Permalink to &quot;8.1 只有状态价值还不够直接选动作&quot;">​</a></h3><p>已知模型时，可以利用 (V(s)) 和转移概率计算每个动作的后果。免模型条件下，如果只有 (V(s))，却不知道动作如何改变下一状态，就无法直接完成一步前瞻。因此蒙特卡洛控制通常估计动作价值：</p><p>$$ q_\\pi(s,a)=\\mathbb{E}_\\pi[G_t\\mid S_t=s,A_t=a] $$</p><p>一旦有了 (Q(s,a))，策略就能直接比较同一状态下不同动作的经验回报。</p><h3 id="_8-2-控制仍然由评估和改进组成" tabindex="-1">8.2 控制仍然由评估和改进组成 <a class="header-anchor" href="#_8-2-控制仍然由评估和改进组成" aria-label="Permalink to &quot;8.2 控制仍然由评估和改进组成&quot;">​</a></h3><p>智能体使用当前策略采集回合，用完整回报更新 (Q(s,a))，再提高高价值动作的选择概率。随后，新策略产生新的数据，新的数据继续修正动作价值。这形成“采样、评估、改进、再采样”的闭环。</p><p><img src="'+n+'" alt="蒙特卡洛控制在采样、动作价值估计与策略改进之间循环"></p><h2 id="九、探索为什么是控制问题的生命线" tabindex="-1">九、探索为什么是控制问题的生命线 <a class="header-anchor" href="#九、探索为什么是控制问题的生命线" aria-label="Permalink to &quot;九、探索为什么是控制问题的生命线&quot;">​</a></h2><h3 id="_9-1-贪心过早会让价值表失去证据" tabindex="-1">9.1 贪心过早会让价值表失去证据 <a class="header-anchor" href="#_9-1-贪心过早会让价值表失去证据" aria-label="Permalink to &quot;9.1 贪心过早会让价值表失去证据&quot;">​</a></h3><p>如果智能体总选择当前 (Q) 值最大的动作，初始化误差或少量幸运样本可能让某个动作长期占优。其他动作不再被访问，其估计无法修正。看起来策略已经稳定，实际上只是数据采集停止了。</p><h3 id="_9-2-探索式起点是清晰但很强的假设" tabindex="-1">9.2 探索式起点是清晰但很强的假设 <a class="header-anchor" href="#_9-2-探索式起点是清晰但很强的假设" aria-label="Permalink to &quot;9.2 探索式起点是清晰但很强的假设&quot;">​</a></h3><p>探索式起点（Exploring Starts，探索式起点）假设每个状态动作对都有非零概率成为回合起点。它能帮助理论上保证覆盖，但现实系统通常不能任意把环境重置到任何状态，更不能让真实车辆从危险姿态随机开始。</p><h3 id="_9-3-软策略提供更实际的持续探索" tabindex="-1">9.3 软策略提供更实际的持续探索 <a class="header-anchor" href="#_9-3-软策略提供更实际的持续探索" aria-label="Permalink to &quot;9.3 软策略提供更实际的持续探索&quot;">​</a></h3><p>常见替代方案是 (\\varepsilon)-贪心策略：大部分概率选择当前最优动作，同时保留小概率探索其他动作。若动作数为 (|\\mathcal A(s)|)，一种写法是：</p><p>$$ \\pi(a|s)= \\begin{cases} 1-\\varepsilon+\\frac{\\varepsilon}{|\\mathcal A(s)|}, &amp; a\\in\\arg\\max_{a&#39;}Q(s,a&#39;)\\ \\frac{\\varepsilon}{|\\mathcal A(s)|}, &amp; \\text{其他动作} \\end{cases} $$</p><p>它让每个动作保持非零概率，策略因此是 (\\varepsilon)-软的。探索率过大会损害当前表现，过小又可能覆盖不足，所以应记录探索率、访问计数和策略变化，而不是只看平均回报。</p><h2 id="十、同策略蒙特卡洛控制在学谁的策略" tabindex="-1">十、同策略蒙特卡洛控制在学谁的策略 <a class="header-anchor" href="#十、同策略蒙特卡洛控制在学谁的策略" aria-label="Permalink to &quot;十、同策略蒙特卡洛控制在学谁的策略&quot;">​</a></h2><h3 id="_10-1-行为策略与目标策略相同" tabindex="-1">10.1 行为策略与目标策略相同 <a class="header-anchor" href="#_10-1-行为策略与目标策略相同" aria-label="Permalink to &quot;10.1 行为策略与目标策略相同&quot;">​</a></h3><p>同策略（On-Policy，同策略）方法用当前正在改进的策略采集数据，也评估和优化这个策略本身。采用 (\\varepsilon)-贪心时，最终学习对象包含持续探索行为，并非完全确定性的纯贪心策略。</p><h3 id="_10-2-回合级更新带来明显延迟" tabindex="-1">10.2 回合级更新带来明显延迟 <a class="header-anchor" href="#_10-2-回合级更新带来明显延迟" aria-label="Permalink to &quot;10.2 回合级更新带来明显延迟&quot;">​</a></h3><p>每个回合开始时，智能体按当前策略行动；回合结束后，才用所有 ((S_t,A_t,G_t)) 更新动作价值并改进策略。长回合中的早期错误要等很久才能收到反馈。如果回合可能持续数小时，这种延迟不仅训练慢，也增加内存和故障恢复负担。</p><h3 id="_10-3-策略变化必须与数据语义对应" tabindex="-1">10.3 策略变化必须与数据语义对应 <a class="header-anchor" href="#_10-3-策略变化必须与数据语义对应" aria-label="Permalink to &quot;10.3 策略变化必须与数据语义对应&quot;">​</a></h3><p>若采样途中频繁修改行为策略，再把整条轨迹当作由单一固定策略生成，分析会变得含混。基础实现通常以回合为更新单位，或准确记录每个动作发生时的行为概率，为后续异策略校正保留依据。</p><h2 id="十一、异策略学习为什么需要重要性采样" tabindex="-1">十一、异策略学习为什么需要重要性采样 <a class="header-anchor" href="#十一、异策略学习为什么需要重要性采样" aria-label="Permalink to &quot;十一、异策略学习为什么需要重要性采样&quot;">​</a></h2><h3 id="_11-1-数据策略和学习目标可以不同" tabindex="-1">11.1 数据策略和学习目标可以不同 <a class="header-anchor" href="#_11-1-数据策略和学习目标可以不同" aria-label="Permalink to &quot;11.1 数据策略和学习目标可以不同&quot;">​</a></h3><p>异策略（Off-Policy，异策略）方法区分行为策略 (b) 与目标策略 (\\pi)。数据由 (b) 采集，却希望估计 (\\pi) 的价值。这允许复用旧策略、人工驾驶或其他控制器产生的轨迹，但两种策略造成的轨迹分布不同，不能直接混用平均回报。</p><h3 id="_11-2-概率比修正分布差异" tabindex="-1">11.2 概率比修正分布差异 <a class="header-anchor" href="#_11-2-概率比修正分布差异" aria-label="Permalink to &quot;11.2 概率比修正分布差异&quot;">​</a></h3><p>从时刻 (t) 开始，一条轨迹的重要性采样比率（Importance Sampling Ratio，重要性采样比率）可写为：</p><p>$$ \\rho_{t:T-1}=\\prod_{k=t}^{T-1}\\frac{\\pi(A_k|S_k)}{b(A_k|S_k)} $$</p><p>它衡量这段动作序列在目标策略下与行为策略下的相对可能性。普通重要性采样直接用比率加权回报；加权重要性采样再用权重总和归一化。前者在合适条件下具有无偏性质但方差可能极大，后者有限样本下通常有偏，却更稳定并具有一致性。</p><h3 id="_11-3-覆盖条件不能被公式掩盖" tabindex="-1">11.3 覆盖条件不能被公式掩盖 <a class="header-anchor" href="#_11-3-覆盖条件不能被公式掩盖" aria-label="Permalink to &quot;11.3 覆盖条件不能被公式掩盖&quot;">​</a></h3><p>只要 (\\pi(a|s)&gt;0)，就必须有 (b(a|s)&gt;0)。如果目标策略可能选择某动作，而行为策略从未选择它，分母为零，历史数据也没有证据回答该动作会怎样。重要性采样只能修正概率权重，不能创造从未观察到的反事实数据。</p><p>长轨迹中多个概率比连续相乘，还可能让权重接近零或极大，导致有效样本量骤降。因此，离线数据很多不等于目标策略估计可靠；行为覆盖、权重分布和有效样本量必须一起检查。</p><h2 id="十二、高方差从哪里来" tabindex="-1">十二、高方差从哪里来 <a class="header-anchor" href="#十二、高方差从哪里来" aria-label="Permalink to &quot;十二、高方差从哪里来&quot;">​</a></h2><h3 id="_12-1-一次动作会继承整条未来的随机性" tabindex="-1">12.1 一次动作会继承整条未来的随机性 <a class="header-anchor" href="#_12-1-一次动作会继承整条未来的随机性" aria-label="Permalink to &quot;12.1 一次动作会继承整条未来的随机性&quot;">​</a></h3><p>(G_t) 包含时刻 (t) 之后的全部奖励。环境随机性、后续动作选择、回合长度和偶发事件都会影响同一个学习目标。越靠近回合开头，通常累积的不确定性越多，回报波动也可能越大。</p><h3 id="_12-2-无偏目标不等于低误差算法" tabindex="-1">12.2 无偏目标不等于低误差算法 <a class="header-anchor" href="#_12-2-无偏目标不等于低误差算法" aria-label="Permalink to &quot;12.2 无偏目标不等于低误差算法&quot;">​</a></h3><p>在固定策略和正确回合语义下，完整回报可以作为价值的无偏样本，但有限数据的估计仍可能有很大方差。高方差意味着不同随机种子会得到截然不同的曲线，也意味着需要更多回合才能看清真实趋势。</p><p>固定学习率、策略持续变化、截断处理、函数逼近和异策略加权还会引入额外影响。因此，“蒙特卡洛没有自举偏差”不能被简化成“蒙特卡洛估计总是无偏且更准确”。必须针对实际数据生成和更新方式判断。</p><h2 id="十三、动态规划、蒙特卡洛与时序差分怎样区分" tabindex="-1">十三、动态规划、蒙特卡洛与时序差分怎样区分 <a class="header-anchor" href="#十三、动态规划、蒙特卡洛与时序差分怎样区分" aria-label="Permalink to &quot;十三、动态规划、蒙特卡洛与时序差分怎样区分&quot;">​</a></h2><h3 id="_13-1-动态规划用模型期望和自举" tabindex="-1">13.1 动态规划用模型期望和自举 <a class="header-anchor" href="#_13-1-动态规划用模型期望和自举" aria-label="Permalink to &quot;13.1 动态规划用模型期望和自举&quot;">​</a></h3><p>动态规划知道完整模型，通过全部后继分支计算期望，并使用已有价值估计更新当前价值。它不必等待真实回合，但会受到模型可得性和全状态遍历成本限制。</p><h3 id="_13-2-蒙特卡洛用完整样本回报" tabindex="-1">13.2 蒙特卡洛用完整样本回报 <a class="header-anchor" href="#_13-2-蒙特卡洛用完整样本回报" aria-label="Permalink to &quot;13.2 蒙特卡洛用完整样本回报&quot;">​</a></h3><p>蒙特卡洛不需要完整模型，也不使用估计的后继价值。它必须等待终点，通常方差较高，却能直接从真实或模拟经验学习。</p><h3 id="_13-3-时序差分用局部样本和自举" tabindex="-1">13.3 时序差分用局部样本和自举 <a class="header-anchor" href="#_13-3-时序差分用局部样本和自举" aria-label="Permalink to &quot;13.3 时序差分用局部样本和自举&quot;">​</a></h3><p>时序差分同样免模型，但每观察一步就可以用 (R_{t+1}+\\gamma V(S_{t+1})) 更新当前价值。它无需等回合结束，通常方差更低，却把当前估计放进目标，因而具有自举带来的偏差和传播特性。</p><p><img src="'+s+'" alt="动态规划、蒙特卡洛与时序差分的核心差异"></p><h2 id="十四、放进自动驾驶任务前必须补哪些边界" tabindex="-1">十四、放进自动驾驶任务前必须补哪些边界 <a class="header-anchor" href="#十四、放进自动驾驶任务前必须补哪些边界" aria-label="Permalink to &quot;十四、放进自动驾驶任务前必须补哪些边界&quot;">​</a></h2><h3 id="_14-1-回合定义会直接改变学习目标" tabindex="-1">14.1 回合定义会直接改变学习目标 <a class="header-anchor" href="#_14-1-回合定义会直接改变学习目标" aria-label="Permalink to &quot;14.1 回合定义会直接改变学习目标&quot;">​</a></h3><p>一次变道、一个路口、一段固定路线或整趟行程，都可以被定义为回合。回合越长，延迟反馈与方差问题越明显；回合过短，又可能切断动作的长期后果。超时截断是否保留尾部价值，也会影响“未完成任务”究竟被当成失败还是未知后续。</p><h3 id="_14-2-真实道路不能承担无约束探索" tabindex="-1">14.2 真实道路不能承担无约束探索 <a class="header-anchor" href="#_14-2-真实道路不能承担无约束探索" aria-label="Permalink to &quot;14.2 真实道路不能承担无约束探索&quot;">​</a></h3><p>(\\varepsilon)-贪心在网格世界里只是偶尔走错一步，在真实车辆上却可能意味着随机转向或随机加速。蒙特卡洛控制的探索要求不能直接转化为道路测试方案。安全约束、仿真验证、规则控制器、Safety Shield（安全屏蔽器）和人工接管属于独立安全层，不能由平均回报自动保证。</p><h3 id="_14-3-罕见危险事件最难靠平均值学稳" tabindex="-1">14.3 罕见危险事件最难靠平均值学稳 <a class="header-anchor" href="#_14-3-罕见危险事件最难靠平均值学稳" aria-label="Permalink to &quot;14.3 罕见危险事件最难靠平均值学稳&quot;">​</a></h3><p>碰撞和失控很少发生，却是最重要的尾部风险。若奖励主要由大量正常回合主导，平均回报可能掩盖低概率高损失事件。评估时至少应单独报告碰撞率、越界率、约束违反率、最坏分位数表现和不同场景覆盖，而不是只报告平均累计奖励。</p><h3 id="_14-4-日志复用受到异策略覆盖限制" tabindex="-1">14.4 日志复用受到异策略覆盖限制 <a class="header-anchor" href="#_14-4-日志复用受到异策略覆盖限制" aria-label="Permalink to &quot;14.4 日志复用受到异策略覆盖限制&quot;">​</a></h3><p>人类驾驶日志通常集中在合理动作附近，危险动作没有数据是正常现象。用这些日志评估一个差异很大的目标策略时，重要性权重可能不稳定，甚至违反覆盖条件。离线数据不能回答所有“如果当时采取另一动作会怎样”的问题，模型假设、保守学习或受控仿真仍然不可缺少。</p><h2 id="十五、一个最小实验应该验证什么" tabindex="-1">十五、一个最小实验应该验证什么 <a class="header-anchor" href="#十五、一个最小实验应该验证什么" aria-label="Permalink to &quot;十五、一个最小实验应该验证什么&quot;">​</a></h2><h3 id="_15-1-先选择真正的回合式小环境" tabindex="-1">15.1 先选择真正的回合式小环境 <a class="header-anchor" href="#_15-1-先选择真正的回合式小环境" aria-label="Permalink to &quot;15.1 先选择真正的回合式小环境&quot;">​</a></h3><p>可以使用能稳定终止的网格任务或纸牌任务。固定策略后采集大量回合，分别实现首次访问和每次访问预测。实验目标不是展示漂亮动画，而是确认回报计算、访问判定和均值更新与定义一致。</p><h3 id="_15-2-同时记录估计值和不确定性" tabindex="-1">15.2 同时记录估计值和不确定性 <a class="header-anchor" href="#_15-2-同时记录估计值和不确定性" aria-label="Permalink to &quot;15.2 同时记录估计值和不确定性&quot;">​</a></h3><p>选取几个访问频率不同的状态，记录其访问次数、价值估计和回报标准差。用多个随机种子重复，比较样本较少与样本充足时的波动。若只看总回报，很多索引错误和覆盖问题不会暴露。</p><h3 id="_15-3-用可枚举小环境提供参照" tabindex="-1">15.3 用可枚举小环境提供参照 <a class="header-anchor" href="#_15-3-用可枚举小环境提供参照" aria-label="Permalink to &quot;15.3 用可枚举小环境提供参照&quot;">​</a></h3><p>在小环境中，可以用动态规划得到固定策略的参考价值，再计算蒙特卡洛估计误差。这样能验证“样本平均是否趋近正确答案”，而不是用算法自己的输出证明算法正确。</p><h3 id="_15-4-控制实验必须观察探索覆盖" tabindex="-1">15.4 控制实验必须观察探索覆盖 <a class="header-anchor" href="#_15-4-控制实验必须观察探索覆盖" aria-label="Permalink to &quot;15.4 控制实验必须观察探索覆盖&quot;">​</a></h3><p>加入动作价值和 (\\varepsilon)-贪心策略后，记录每个状态动作对的访问计数。平均回报提高但大量动作从未被访问，不能说明控制已经可靠收敛。还要分别用训练策略和独立评估策略运行，避免探索噪声混入最终性能判断。</p><h2 id="十六、实现时最常见的错误" tabindex="-1">十六、实现时最常见的错误 <a class="header-anchor" href="#十六、实现时最常见的错误" aria-label="Permalink to &quot;十六、实现时最常见的错误&quot;">​</a></h2><h3 id="_16-1-奖励索引错一位" tabindex="-1">16.1 奖励索引错一位 <a class="header-anchor" href="#_16-1-奖励索引错一位" aria-label="Permalink to &quot;16.1 奖励索引错一位&quot;">​</a></h3><p>动作 (A_t) 之后收到的是 (R_{t+1})。如果轨迹数组把状态和奖励下标混用，整个回报都会错位。应先写出短轨迹并手算 (G_t)，再对照程序结果。</p><h3 id="_16-2-把截断当成自然终止" tabindex="-1">16.2 把截断当成自然终止 <a class="header-anchor" href="#_16-2-把截断当成自然终止" aria-label="Permalink to &quot;16.2 把截断当成自然终止&quot;">​</a></h3><p>达到时间上限只说明采样被停止，不一定说明任务未来价值为零。环境接口应区分终止与截断，实验文档要写清尾部如何处理。</p><h3 id="_16-3-把固定学习率叫作普通平均" tabindex="-1">16.3 把固定学习率叫作普通平均 <a class="header-anchor" href="#_16-3-把固定学习率叫作普通平均" aria-label="Permalink to &quot;16.3 把固定学习率叫作普通平均&quot;">​</a></h3><p>(\\alpha=1/N) 才对应逐样本算术平均。固定 (\\alpha) 是另一种加权方式。两者可以都合理，但报告中必须使用准确名称。</p><h3 id="_16-4-只保存回报-不保存行为概率" tabindex="-1">16.4 只保存回报，不保存行为概率 <a class="header-anchor" href="#_16-4-只保存回报-不保存行为概率" aria-label="Permalink to &quot;16.4 只保存回报，不保存行为概率&quot;">​</a></h3><p>如果未来需要异策略评估，却没有记录每个动作在采样时的行为概率，就无法正确计算重要性比率。日志设计应在采集前确定，而不是等数据生成后再补猜。</p><h3 id="_16-5-用单条幸运曲线宣称方法有效" tabindex="-1">16.5 用单条幸运曲线宣称方法有效 <a class="header-anchor" href="#_16-5-用单条幸运曲线宣称方法有效" aria-label="Permalink to &quot;16.5 用单条幸运曲线宣称方法有效&quot;">​</a></h3><p>蒙特卡洛回报天然高方差。至少报告多个随机种子、均值、离散程度、访问覆盖和安全指标。训练回报变高只说明在当前采样与指标下出现改善，不等于策略在新场景中可靠，更不等于满足自动驾驶安全要求。</p><h2 id="十七、接下来进入时序差分学习" tabindex="-1">十七、接下来进入时序差分学习 <a class="header-anchor" href="#十七、接下来进入时序差分学习" aria-label="Permalink to &quot;十七、接下来进入时序差分学习&quot;">​</a></h2><p>蒙特卡洛方法完成了从“已知模型计算”到“未知模型采样”的跨越，但它仍要等完整回合结束。下一个自然问题是：能不能只走一步，就立刻学习？</p><p>下一篇将进入时序差分学习，拆解 (R_{t+1}+\\gamma V(S_{t+1})) 这个一步目标，解释它怎样同时继承蒙特卡洛的采样能力与动态规划的自举思想，并系统比较偏差、方差、在线更新和价值传播速度。</p><h2 id="十八、参考资料" tabindex="-1">十八、参考资料 <a class="header-anchor" href="#十八、参考资料" aria-label="Permalink to &quot;十八、参考资料&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter3/chapter3.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第 3 章表格型方法源码</a></p><p><a href="https://github.com/datawhalechina/easy-rl/blob/master/notebooks/MonteCarlo.ipynb" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》蒙特卡洛配套 Notebook（交互式笔记本）</a></p><p><a href="https://web.stanford.edu/class/psych209/Readings/SuttonBartoIPRLBook2ndEd.pdf" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction（强化学习导论）》第 2 版全文</a></p><p><a href="https://mitpress.mit.edu/9780262039246/reinforcement-learning/" target="_blank" rel="noreferrer">MIT Press（麻省理工学院出版社）第 2 版图书页面</a></p><p><a href="https://www.youtube.com/watch?v=PnHCvfgC_ZA" target="_blank" rel="noreferrer">Google DeepMind（谷歌深度思维）David Silver 强化学习课程第 4 讲</a></p><p>本文为强化学习入门系列第 05 篇。文中公式、示意图与自动驾驶案例均按教学目的重新组织，不构成真实车辆部署或安全论证。</p>',158)])])}const k=e(p,[["render",d]]);export{f as __pageData,k as default};
